<?php
require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';require_once __DIR__.'/../payroll.php';oecrm_require_admin_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}oecrm_require_csrf();$action=$_POST['action']??'';$companyId=oecrm_current_company_id($conn);$year=(int)($_POST['year']??0);$month=(int)($_POST['month']??0);$actor=(int)$_SESSION['adminId'];if($year<2020||$month<1||$month>12){http_response_code(400);exit('Invalid payroll period.');}
if(in_array($action,['generate','recalculate'],true)){oecrm_require_permission($conn,'payroll',$action==='generate'?'generate':'recalculate');try{$runId=oecrm_generate_payroll($conn,$companyId,$year,$month,$actor);oecrm_audit($conn,'payroll',$action,'payroll_run',$runId,'Payroll '.$action.'d',null,['year'=>$year,'month'=>$month]);$_SESSION['payroll_flash']='Payroll calculated successfully.';}catch(Throwable $e){$_SESSION['payroll_error']=$e->getMessage();}header('Location: payrollManagement.php?year='.$year.'&month='.$month);exit;}
$runStmt=mysqli_prepare($conn,'SELECT * FROM payroll_runs WHERE company_id=? AND period_year=? AND period_month=?');mysqli_stmt_bind_param($runStmt,'iii',$companyId,$year,$month);mysqli_stmt_execute($runStmt);$run=mysqli_fetch_assoc(mysqli_stmt_get_result($runStmt));mysqli_stmt_close($runStmt);if(!$run){http_response_code(404);exit('Payroll run not found.');}
if($action==='submit'){oecrm_require_permission($conn,'payroll','generate');if(!$run['attendance_locked']){$_SESSION['payroll_error']='Lock attendance before submitting payroll for approval.';}else{mysqli_query($conn,'UPDATE payroll_runs SET status="pending_approval" WHERE id='.(int)$run['id']);$_SESSION['payroll_flash']='Payroll submitted for approval.';}}
elseif($action==='approve'){oecrm_require_permission($conn,'payroll','approve');if($run['status']!=='pending_approval'){$_SESSION['payroll_error']='Payroll must be submitted before approval.';}elseif(!$run['attendance_locked']){$_SESSION['payroll_error']='Attendance period is not locked.';}else{$stmt=mysqli_prepare($conn,'UPDATE payroll_runs SET status="approved",approved_by=?,approved_at=NOW() WHERE id=?');mysqli_stmt_bind_param($stmt,'ii',$actor,$run['id']);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);mysqli_query($conn,'UPDATE payroll_items SET status="approved" WHERE payroll_run_id='.(int)$run['id']);$_SESSION['payroll_flash']='Payroll approved.';}}
elseif($action==='lock'){oecrm_require_permission($conn,'payroll','lock');if($run['status']!=='approved'){$_SESSION['payroll_error']='Approve payroll before locking.';}else{$stmt=mysqli_prepare($conn,'UPDATE payroll_runs SET status="locked",locked_by=?,locked_at=NOW() WHERE id=?');mysqli_stmt_bind_param($stmt,'ii',$actor,$run['id']);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$items=mysqli_query($conn,'SELECT * FROM payroll_items WHERE payroll_run_id='.(int)$run['id']);while($item=mysqli_fetch_assoc($items)){if((float)$item['retention_amount']>0){$bal=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COALESCE(SUM(CASE transaction_type WHEN "hold" THEN amount WHEN "release" THEN -amount ELSE amount END),0) balance FROM retention_ledger WHERE employee_id='.(int)$item['employee_id']));$after=(float)$bal['balance']+(float)$item['retention_amount'];$stmt=mysqli_prepare($conn,'INSERT INTO retention_ledger(employee_id,payroll_item_id,transaction_type,amount,balance_after,notes,created_by) VALUES(?,? ,"hold",?,?,"Payroll retention",?)');mysqli_stmt_bind_param($stmt,'iiddi',$item['employee_id'],$item['id'],$item['retention_amount'],$after,$actor);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);}}$_SESSION['payroll_flash']='Payroll locked successfully.';}}
else{http_response_code(400);exit('Invalid action.');}
oecrm_audit($conn,'payroll',$action,'payroll_run',$run['id'],'Payroll '.$action,null,['year'=>$year,'month'=>$month]);header('Location: payrollManagement.php?year='.$year.'&month='.$month);exit;